using System.Globalization;
using Saldo360.Application.Workspaces;
using Saldo360.Domain.Common;
using Saldo360.Domain.Goals;
namespace Saldo360.Application.Goals;
public sealed class FinancialGoalAllocationService(IFinancialWorkspaceRepository workspaces,IFinancialGoalRepository goals,IFinancialGoalAllocationRepository repository,TimeProvider time)
{
 public async Task<GoalAllocationResult> CreateAsync(Guid workspaceId,Guid goalId,Guid userId,FinancialGoalAllocationType type,GoalAllocationInput input,CancellationToken ct){if(!await Member(workspaceId,userId,ct))return new(GoalAllocationAccess.NotFound,null,null);var goal=await goals.FindAsync(workspaceId,goalId,ct);if(goal is null)return new(GoalAllocationAccess.NotFound,null,null);if(type==FinancialGoalAllocationType.Contribution&&goal.Status!=FinancialGoalStatus.Active)return new(GoalAllocationAccess.Conflict,null,null,"Objetivo não está ativo para receber aportes.");if(type==FinancialGoalAllocationType.Withdrawal&&goal.Status==FinancialGoalStatus.Archived)return new(GoalAllocationAccess.Conflict,null,null,"Objetivo arquivado não permite retiradas.");var e=new Dictionary<string,string[]>();var op=input.OperationId??Guid.Empty;var account=input.FinancialAccountId??Guid.Empty;var date=input.EffectiveDate??default;if(op==Guid.Empty)e["operationId"]=["Informe um OperationId válido."];if(account==Guid.Empty)e["financialAccountId"]=["Informe a conta financeira."];if(!decimal.TryParse(input.Amount,NumberStyles.AllowDecimalPoint,CultureInfo.InvariantCulture,out var amount)||amount<=0||Money.Validate(amount,"O valor") is not null)e["amount"]=["Informe um valor positivo com até duas casas."];var today=Today();if(input.EffectiveDate is null)e["effectiveDate"]=["Informe a data efetiva."];else if(date!=today)e["effectiveDate"]=["A data efetiva deve ser hoje."];if(e.Count>0)return new(GoalAllocationAccess.Invalid,null,e);var existing=await repository.GetByOperationAsync(workspaceId,op,ct);if(existing is not null){if(await repository.PayloadMatchesAsync(workspaceId,op,goalId,account,type,amount,date,input.Description,ct))return new(GoalAllocationAccess.Allowed,existing,null);return new(GoalAllocationAccess.Conflict,null,null,"OperationId já utilizado com conteúdo diferente.");}var allocation=FinancialGoalAllocation.Create(workspaceId,goalId,account,type,amount,date,op,string.IsNullOrWhiteSpace(input.Description)?null:input.Description.Trim(),time.GetUtcNow());var created=await repository.TryCreateAsync(allocation,goal.TargetAmount,ct);if(created.Access==GoalAllocationAccess.Conflict&&await repository.GetByOperationAsync(workspaceId,op,ct) is { } concurrent)return await repository.PayloadMatchesAsync(workspaceId,op,goalId,account,type,amount,date,input.Description,ct)?new(GoalAllocationAccess.Allowed,concurrent,null):new(GoalAllocationAccess.Conflict,null,null,"OperationId já utilizado com conteúdo diferente.");return created;}
 public async Task<IReadOnlyList<FinancialGoalAllocationDto>?> ListAsync(Guid workspaceId,Guid goalId,Guid userId,CancellationToken ct)=>await Member(workspaceId,userId,ct)&&await goals.FindAsync(workspaceId,goalId,ct) is not null?await repository.ListAsync(workspaceId,goalId,ct):null;
 public async Task<GoalProgressDto?> ProgressAsync(Guid workspaceId,Guid goalId,Guid userId,CancellationToken ct){if(!await Member(workspaceId,userId,ct))return null;var g=await goals.FindAsync(workspaceId,goalId,ct);return g is null?null:await repository.ProgressAsync(workspaceId,goalId,g.TargetAmount,ct);}
 public async Task<IReadOnlyList<GoalAccountAvailabilityDto>?> AvailabilityAsync(Guid workspaceId,Guid userId,CancellationToken ct)=>await Member(workspaceId,userId,ct)?await repository.ListAccountsAvailabilityAsync(workspaceId,ct):null;
 public async Task<FinancialGoalSummaryDto?> SummaryAsync(Guid workspaceId,Guid userId,CancellationToken ct)=>await Member(workspaceId,userId,ct)?await repository.SummaryAsync(workspaceId,ct):null;
 public async Task<GoalAllocationResult> CancelAsync(Guid workspaceId,Guid goalId,Guid allocationId,Guid userId,CancellationToken ct){if(!await Member(workspaceId,userId,ct))return new(GoalAllocationAccess.NotFound,null,null);var a=await repository.FindAsync(workspaceId,goalId,allocationId,ct);if(a is null)return new(GoalAllocationAccess.NotFound,null,null);if(a.CancelledAt is not null)return new(GoalAllocationAccess.Allowed,await repository.GetByOperationAsync(workspaceId,a.OperationId,ct),null);if(a.OperationType==FinancialGoalAllocationType.Withdrawal&&await repository.AvailabilityAsync(workspaceId,a.FinancialAccountId,ct) is{ } available&&available.UnallocatedBalance-a.Amount<0)return new(GoalAllocationAccess.Conflict,null,null,"O cancelamento da retirada excederia o saldo não alocado.");a.Cancel(time.GetUtcNow());await repository.SaveAsync(ct);return new(GoalAllocationAccess.Allowed,await repository.GetByOperationAsync(workspaceId,a.OperationId,ct),null);}
 private DateOnly Today(){var id=OperatingSystem.IsWindows()?"E. South America Standard Time":"America/Sao_Paulo";return DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(time.GetUtcNow(),TimeZoneInfo.FindSystemTimeZoneById(id)).Date);}
 private async Task<bool> Member(Guid f,Guid u,CancellationToken ct)=>await workspaces.GetOwnerRoleAsync(f,u,ct) is not null;
}
